mode <- commandArgs(TRUE)[1]
source("pre.R")
if (mode == "attached") suppressPackageStartupMessages(library(bit64)) else if (mode == "loaded") invisible(loadNamespace("bit64"))
B <- function(...) as_integer64(int64(c(...)))
z <- int64(c(-1, NA, 3)); u <- uint64(c(3, NA, 0)); i8 <- int128(c(-1,NA,3)); d <- decimal128(c("-1.00", NA, "3.00"), 10, 2)
b <- B(-1, NA, 3); b2 <- B(3, -1, NA)
for (nm in c("z","u","i8","d")) { w <- get(nm); cat("----", nm, "\n")
  show("zu_match(w, b2)", zu_match(w, b2)); show("zu_match(b2, w)", zu_match(b2, w)); show("w %zin% b2", w %zin% b2); show("b2 %zin% w", b2 %zin% w)
  show("w == b", w == b); show("b == w", b == w); show("w < b2", w < b2); show("b2 > w", b2 > w); show("w != b", w != b)
  show("w + b", w + b); show("b + w", b + w); show("w * b", w * b); show("b - w", b - w); show("b %/% w", b %/% w); show("w %% b2", w %% b2)
  show("c(w, b)", c(w, b)); show("{w[1:3] <- b2}", {w2 <- w; w2[1:3] <- b2; w2}); show("{w[[1]] <- B(NA)}", {w2 <- w; w2[[1]] <- B(NA); w2}); show("{w[2] <- B(-1)}", {w2 <- w; w2[2] <- B(-1); w2})
  show("pmax(w, b2)", pmax(w, b2)); show("pmin(w, b2, na.rm=TRUE)", pmin(w, b2, na.rm=TRUE)); show("max(w, b2, na.rm=TRUE)", max(w, b2, na.rm=TRUE)); show("sum(w, b2, na.rm=TRUE)", sum(w, b2, na.rm=TRUE)); show("sum(w,b2)", sum(w, b2)); show("range", range(w, b, na.rm=TRUE))
  show("zu_ifelse(c(T,F,T), w, b2)", zu_ifelse(c(TRUE,FALSE,TRUE), w, b2)); show("zu_ifelse(c(T,F,T), b2, w)", zu_ifelse(c(TRUE,FALSE,TRUE), b2, w))
  show("append(w, b2)", append(w, b2)); show("all.equal(w, b)", all.equal(w, b)); show("identical values", all(as.character(w) == as.character(int64(b)), na.rm=TRUE))
  show("vec_c(w, b)", vctrs::vec_c(w, b)); show("vec_cast(b, w)", vctrs::vec_cast(b, w)); show("vec_match(w, b2)", vctrs::vec_match(w, b2)); show("vec_equal(w, b)", vctrs::vec_equal(w, b)); show("vec_in", vctrs::vec_in(b2, w))
  show("vec_rbind", vctrs::vec_rbind(data.frame(k=I(1))[0,,drop=FALSE][,0], tibble::tibble(k=w), tibble::tibble(k=b))$k)
  show("zu_vapply", zu_vapply(1:3, function(i) B(-1, NA, 3), w[c(1,1,1)]))
  show("merge", {m <- merge(data.frame(k=w, a=1:3), data.frame(k=b2, b=1:3)); m})
  show("unique(c(w,b2))", unique(c(w, b2))); show("setdiff", base::setdiff(w, b2)); show("union", base::union(w, b2)); show("%in%", base::`%in%`(w, b2)); show("match", base::match(w, b2))
}
show("bit_and", bit_and(z, b2)); show("bit_or", bit_or(u, b2)); show("checked_add", tryCatch(checked_add(z, b2), error=function(e) class(e)[1])); show("wrapping_mul", wrapping_mul(z, b2)); show("z ^ B(2,2,2)", z ^ B(2,2,2)); show("z / b2", z / b2)
show("seq(int64(1), B(3))", seq(int64(1), B(3))); show("seq_zu(1L, B(3))", tryCatch(seq_zu(1L, B(3)), error=function(e) conditionMessage(e))); show("seq(int64(1), by=B(2), length.out=3)", seq(int64(1), by=B(2), length.out=3))
show("rep(z, times=B(2))", rep(z, times=B(2))); show("rep(z, each=int64(2))", rep(z, each=int64(2))); show("rep(z, times=uint64(2))", rep(z, times=uint64(2))); show("rep(z, length.out=int64(5))", rep(z, length.out=int64(5)))
show("z[B(3)]", z[B(3)]); show("z[uint64(3)]", z[uint64(3)]); show("z[[int128(3)]]", z[[int128(3)]]); show("z[int64(-1)]", z[int64(-1)]); show("z[int64(c(1,NA))]", z[int64(c(1,NA))]); show("z[int64(5)]", z[int64(5)]); show("z[int64(0)]", z[int64(0)])
show("{z[B(3)] <- 9L}", {z2<-z; z2[B(3)] <- 9L; z2}); show("{z[uint64(3)] <- 9L}", {z2<-z; z2[uint64(3)] <- 9L; z2}); show("{z[[int64(3)]] <- 9L}", {z2<-z; z2[[int64(3)]] <- 9L; z2}); show("{z[int64(5)] <- 9L}", {z2<-z; z2[int64(5)] <- 9L; z2})
show("head(z, int64(2))", head(z, int64(2))); show("tail(z, int64(1))", tail(z, int64(1))); show("diff(z, lag=int64(1))", diff(int64(1:4), lag=int64(2))); show("round(int64(1234), int64(-2))", round(int64(1234), int64(-2))); show("bit_shl(int64(1), int64(3))", tryCatch(bit_shl(int64(1), int64(3)), error=function(e) conditionMessage(e))); show("int64(2)^int64(3)", int64(2)^int64(3)); show("decimal128(int64(5), int64(10), int64(2))", tryCatch(decimal128(int64(5), int64(10), int64(2)), error=function(e) conditionMessage(e)))
show("zu_ifelse(test=B)", zu_ifelse(B(1,0,NA,-1), int64(1), int64(2))); show("zu_ifelse(test=int64)", zu_ifelse(int64(c(1,0,NA,-1)), int64(1), int64(2))); show("zu_ifelse(test=u128)", zu_ifelse(uint128(c(1,0,NA,7)), int64(1), int64(2)))
show("z & B", z & b); show("!B via zu", !z); show("xor", xor(z, b)); show("isTRUE(z | b)", z | B(0,0,0))
show("int64(B)", int64(b)); show("int128(B)", int128(b)); show("uint64(B)", uint64(B(3,NA,0))); show("decimal128(B)", decimal128(b, 10, 2)); show("as.character(int64(B))", as.character(int64(b)))
show("zu_common_type(B, u)", zu_common_type(b, u)); show("is_zuint(B)", tryCatch(is_zuint(b), error=function(e) "n/a"))
